<?php declare(strict_types=1);namespace QualitySystem\Domain\CourseReport;final class CourseReportValidator{public static function validate(array $i):array{$e=[];foreach(['course_code'=>'Course code','course_title'=>'Course title','academic_year'=>'Academic year','semester'=>'Semester']as$f=>$label)if(trim((string)($i[$f]??''))==='')$e[]="$label is required.";foreach(['students_enrolled','students_passed','students_failed','students_starting','students_completed']as$f){$v=$i[$f]??'';if($v!==''&&(!ctype_digit((string)$v)||(int)$v>100000))$e[]=ucwords(str_replace('_',' ',$f)).' must be a non-negative whole number.';}if(($i['report_date']??'')!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)$i['report_date']))$e[]='Report date is invalid.';return$e;}}
